window.t = function(key) {
  const lang = localStorage.getItem('lamim_lang') || 'en';
  if (lang === 'bn' && Translations[key]) {
    return Translations[key];
  }
  return key;
};

// Translate numbers to Bengali numerals
window.n = function(num) {
  const lang = localStorage.getItem('lamim_lang') || 'en';
  if (lang !== 'bn') return num;
  const bnNums = ['০','১','২','৩','৪','৫','৬','৭','৮','৯'];
  return String(num).replace(/\d/g, d => bnNums[d]);
};
// Auto-Translator MutationObserver
const autoTranslateObserver = new MutationObserver((mutations) => {
  const isBn = (localStorage.getItem('lamim_lang') || 'en') === 'bn';
  const bnNums = ['০','১','২','৩','৪','৫','৬','৭','৮','৯'];
  const enNums = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'};

  autoTranslateObserver.disconnect();

  function processTextNode(node) {
    const p = node.parentElement;
    if (!p) return;
    // Skip script, style, SVG internals, inputs, textareas, and code blocks
    const tag = p.tagName;
    if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'CODE' || tag === 'PRE') return;
    if (p.closest('svg')) return; // Never touch SVG content - breaks viewBox, coordinates, etc.
    if (p.closest('[data-no-translate], [contenteditable="true"], .notranslate')) return; // Allow opting out
    let text = node.nodeValue;
    if (!text || !text.trim()) return;

    let changed = false;
    
    // 1. Text Translation
    let trimmed = text.trim();
    if (isBn && Translations[trimmed]) {
      text = text.replace(trimmed, Translations[trimmed]);
      changed = true;
    }

    // 2. Number Translation
    if (isBn && /\d/.test(text)) {
      text = text.replace(/\d/g, d => bnNums[d]);
      changed = true;
    } else if (!isBn && /[০-৯]/.test(text)) {
      text = text.replace(/[০-৯]/g, d => enNums[d]);
      changed = true;
    }

    if (changed && node.nodeValue !== text) {
      node.nodeValue = text;
    }
  }

  for (let m of mutations) {
    if (m.type === 'characterData') {
      processTextNode(m.target);
    } else if (m.type === 'childList') {
      m.addedNodes.forEach(node => {
        if (node.nodeType === Node.TEXT_NODE) {
          processTextNode(node);
        } else if (node.nodeType === Node.ELEMENT_NODE) {
           if (node.tagName === 'SCRIPT' || node.tagName === 'STYLE') return;
           const walk = document.createTreeWalker(node, NodeFilter.SHOW_TEXT, null, false);
           let n;
           while (n = walk.nextNode()) {
             processTextNode(n);
           }
        }
      });
    }
  }

  autoTranslateObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
});

// Start observer as soon as possible
if (document.body) {
  autoTranslateObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
} else {
  window.addEventListener('DOMContentLoaded', () => {
    autoTranslateObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
    
    // Run an initial pass on the whole body
    const isBn = (localStorage.getItem('lamim_lang') || 'en') === 'bn';
    if (isBn) {
      autoTranslateObserver.disconnect();
      const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
      let n;
      while (n = walk.nextNode()) {
        processTextNode(n);
      }
      autoTranslateObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
    }
  });
}




/* --- prayer-notifier.js --- */
/* =============================================
   LAMIM — PRAYER NOTIFICATION SCHEDULER
   Checks every 30s and fires notifications
   at prayer times (Fajr, Dhuhr, Asr, Maghrib, Isha)
   ============================================= */

const PrayerNotifier = {
  _notified: null,          // Map of prayerKey -> true (today's sent notifications)
  _intervalId: null,
  _checkInterval: 30000,    // Check every 30 seconds
  _catchUpWindow: 30 * 60 * 1000, // Catch up on prayers missed up to 30 min ago (tab throttled)

  init() {
    if (this._intervalId) return;
    
    const settings = DB.getSettings();
    if (!settings.notifications) return;
    
    // Only start if permission is already granted — NEVER auto-prompt here
    if (!('Notification' in window) || Notification.permission !== 'granted') {
      return;
    }

    // Load today's already-sent notifications from localStorage, reset on new local day
    let notified = {};
    try { notified = JSON.parse(localStorage.getItem('lamim_notified') || '{}'); } catch (e) { notified = {}; }
    const lastDate = localStorage.getItem('lamim_notified_date') || '';
    if (lastDate !== Utils.todayStr()) {
      notified = {};
      localStorage.removeItem('lamim_notified');
    }
    this._notified = notified;

    // Start the checker loop
    this._intervalId = setInterval(() => this.check(), this._checkInterval);
    
    // Also check immediately
    setTimeout(() => this.check(), 2000);
    
  },

  stop() {
    if (this._intervalId) {
      clearInterval(this._intervalId);
      this._intervalId = null;
    }
  },


  check() {
    const settings = DB.getSettings();
    if (!settings.notifications) return;
    if (!('Notification' in window) || Notification.permission !== 'granted') return;

    const times = Utils.calcPrayerTimes();
    if (!times || times.length === 0) return;

    const now = new Date();
    const todayStr = Utils.todayStr();

    // Roll over to a new local day: clear sent notifications
    if (localStorage.getItem('lamim_notified_date') !== todayStr) {
      this._notified = {};
      localStorage.removeItem('lamim_notified');
      localStorage.setItem('lamim_notified_date', todayStr);
    }

    // Notify for any prayer whose time has just started OR was missed while the
    // tab was throttled/backgrounded (within the catch-up window)
    for (const prayer of times) {
      const diff = now.getTime() - prayer.time.getTime();

      if (diff >= 0 && diff < this._catchUpWindow) {
        const prayerKey = `${todayStr}_${prayer.name}`;

        if (!this._notified[prayerKey]) {
          this._notified[prayerKey] = true;
          try {
            localStorage.setItem('lamim_notified', JSON.stringify(this._notified));
            localStorage.setItem('lamim_notified_date', todayStr);
          } catch (e) { /* storage full / disabled — in-memory dedupe still works */ }

          this.sendNotification(prayer);
          return;
        }
      }
    }
  },

  sendNotification(prayer) {
    const prayerNames = {
      fajr: { en: 'Fajr', bn: 'ফজর', emoji: '' },
      dhuhr: { en: 'Dhuhr', bn: 'যোহর', emoji: '️' },
      asr: { en: 'Asr', bn: 'আসর', emoji: '️' },
      maghrib: { en: 'Maghrib', bn: 'মাগরিব', emoji: '' },
      isha: { en: 'Isha', bn: 'এশা', emoji: '' }
    };

    const info = prayerNames[prayer.name] || { en: prayer.name, bn: prayer.name, emoji: '' };
    const lang = localStorage.getItem('lamim_lang') || 'en';
    const isBn = lang === 'bn';

    const title = isBn 
      ? `${info.emoji} ${info.bn} এর সময় হয়েছে!`
      : `${info.emoji} Time for ${info.en}!`;
    
    const body = isBn
      ? `এখনই সালাত আদায় করুন। আল্লাহ আপনাকে কবুল করুন।`
      : `Pray now. May Allah accept your prayer.`;

    try {
      const iconUrl = new URL('assets/icon-192x192.png', window.location.href).href;
      const badgeUrl = new URL('assets/icon-32x32.png', window.location.href).href;

      // Try Service Worker notification first (works in background)
      if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
        navigator.serviceWorker.ready.then(reg => {
          reg.showNotification(title, {
            body: body,
            icon: iconUrl,
            badge: badgeUrl,
            tag: `prayer-${prayer.name}`,
            renotify: true,
            vibrate: [200, 100, 200, 100, 200],
            requireInteraction: true,
            data: { prayer: prayer.name }
          });
        }).catch(() => {
          new Notification(title, { body, icon: iconUrl });
        });
      } else {
        // Fallback to regular Notification API
        new Notification(title, {
          body: body,
          icon: iconUrl,
          tag: `prayer-${prayer.name}`,
          requireInteraction: true
        });
      }

    } catch (e) {
      console.error('[PrayerNotifier] Failed to send notification:', e);
    }
  }
};




/* --- auth.js --- */
/* =============================================
   LAMIM — OFFLINE AUTH/SETUP MODULE
   ============================================= */
const Auth = {
  init() {
    this.selectedGender = null;
    this.bindSetup();
  },

  setGender(gender) {
    this.selectedGender = gender;
    const maleCard = document.getElementById('setup-gender-male');
    const femaleCard = document.getElementById('setup-gender-female');
    if (gender === 'male') {
      maleCard?.classList.add('active');
      femaleCard?.classList.remove('active');
    } else {
      femaleCard?.classList.add('active');
      maleCard?.classList.remove('active');
    }
  },



  nextStep(currentStep) {
    if (currentStep === 1) {
      const nameInput = document.getElementById('setup-name');
      const err = document.getElementById('setup-name-err');
      const name = nameInput ? nameInput.value.trim() : '';
      if (!name) {
        if (nameInput) nameInput.classList.add('input-error');
        if (err) { err.textContent = 'Name is required'; err.classList.add('show'); }
        if (nameInput) nameInput.focus();
        return;
      }
      if (name.length < 2 || name.length > 50) {
        if (nameInput) nameInput.classList.add('input-error');
        if (err) { err.textContent = 'Name must be 2–50 characters'; err.classList.add('show'); }
        if (nameInput) nameInput.focus();
        return;
      }
      if (nameInput) nameInput.classList.remove('input-error');
      if (err) err.classList.remove('show');
    }
    
    if (currentStep === 2) {
      if (!this.selectedGender) {
        Utils.toast('Please select a gender to continue', 'warning');
        return; // Prevent skipping
      }
    }

    // Step 3 (DOB) always has a valid value via drum picker, so we can proceed safely
    this.goToStep(currentStep + 1);
  },

  prevStep(currentStep) {
    this.goToStep(currentStep - 1);
  },

  goToStep(stepNum) {
    const wrapper = document.getElementById('setup-steps-wrapper');
    if (!wrapper) return;

    // 4 steps — each is 25% wide
    const translatePct = -((stepNum - 1) * 25);
    wrapper.style.transform = `translateX(${translatePct}%)`;

    // Update progress dots
    const dots = document.querySelectorAll('.setup-dot');
    dots.forEach((dot, idx) => {
      dot.classList.toggle('active', idx === (stepNum - 1));
    });

    // Re-trigger anim-target animations on the new step
    const newStep = document.querySelector(`.setup-step[data-step="${stepNum}"]`);
    if (newStep) {
      newStep.querySelectorAll('.anim-target').forEach((el, i) => {
        el.style.animation = 'none';
        void el.offsetHeight;
        el.style.animation = '';
        el.style.animationDelay = (i * 0.08) + 's';
      });
    }

    // Initialise DOB drum picker when arriving at step 3
    if (stepNum === 3) this.initDOBPicker();
  },

  initDOBPicker() {
    if (this._dobReady) return; // only build once
    this._dobReady = true;

    const ITEM_H = 44;
    const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    let selD = 0, selM = 0, selY = 60; // defaults: day=1, Jan, year=2000

    const fill = (colId, labels, defaultIdx) => {
      const col = document.getElementById(colId);
      if (!col) return;
      let h = '<div class="dob-drum-pad"></div>';
      labels.forEach(l => { h += `<div class="dob-drum-item">${l}</div>`; });
      h += '<div class="dob-drum-pad"></div>';
      col.innerHTML = h;
      requestAnimationFrame(() => { col.scrollTop = defaultIdx * ITEM_H; });

      let t;
      col.addEventListener('scroll', () => {
        clearTimeout(t);
        t = setTimeout(() => {
          const idx = Math.round(col.scrollTop / ITEM_H);
          col.scrollTo({ top: idx * ITEM_H, behavior: 'smooth' });
          return idx;
        }, 80);
      }, { passive: true });
      return col;
    };

    const days = Array.from({length:31}, (_,i) => String(i+1).padStart(2,'0'));
    const years = Array.from({length:86}, (_,i) => String(1930+i));

    const colD = fill('dob-col-d', days, selD);
    const colM = fill('dob-col-m', MONTHS, selM);
    const colY = fill('dob-col-y', years, selY);

    const sync = () => {
      if (colD) selD = Math.round(colD.scrollTop / ITEM_H);
      if (colM) selM = Math.round(colM.scrollTop / ITEM_H);
      if (colY) selY = Math.round(colY.scrollTop / ITEM_H);
      const inp = document.getElementById('setup-dob');
      if (inp) inp.value = `${1930+selY}-${String(selM+1).padStart(2,'0')}-${String(selD+1).padStart(2,'0')}`;
    };

    [colD, colM, colY].forEach(col => {
      if (!col) return;
      col.addEventListener('scroll', () => { clearTimeout(col._st); col._st = setTimeout(sync, 120); }, {passive:true});
    });

    sync();
  },

  async detectLocation(e) {
    if (this._isSyncingLocation) return;
    this._isSyncingLocation = true;

    const statusText = document.getElementById('setup-location-status');
    const icon = document.getElementById('setup-detect-icon');
    const latInput = document.getElementById('setup-lat');
    const lngInput = document.getElementById('setup-lng');
    const err = document.getElementById('setup-loc-err');

    if (statusText) statusText.textContent = 'Detecting your coordinates...';
    if (icon) icon.classList.add('rotating');
    if (err) err.classList.remove('show');
    Utils.detectHighPrecisionLocation(
      (res) => {
        if (latInput) latInput.value = res.lat.toFixed(6);
        if (lngInput) lngInput.value = res.lng.toFixed(6);
        if (statusText) statusText.textContent = `Detected: ${res.name}`;
        Utils.toast(`Location detected: ${res.name}`, 'success');
        if (icon) icon.classList.remove('rotating');
        this._isSyncingLocation = false;
      },
      (err) => {
        Utils.toast('Could not detect location. Please input coordinates manually.', 'warning');
        if (statusText) statusText.textContent = 'Auto-detection failed. Enter manually.';
        if (icon) icon.classList.remove('rotating');
        this._isSyncingLocation = false;
      }
    );
  },

  submitSetup() {
    if (this._submitting) return;
    const nameInput = document.getElementById('setup-name');
    const name = (nameInput ? nameInput.value.trim() : '');

    if (!name) {
      this.goToStep(1);
      if (nameInput) nameInput.classList.add('input-error');
      const err = document.getElementById('setup-name-err');
      if (err) { err.textContent = 'Name is required'; err.classList.add('show'); }
      if (nameInput) nameInput.focus();
      return;
    }
    if (name.length < 2 || name.length > 50) {
      this.goToStep(1);
      if (nameInput) nameInput.classList.add('input-error');
      const err = document.getElementById('setup-name-err');
      if (err) { err.textContent = 'Name must be 2–50 characters'; err.classList.add('show'); }
      if (nameInput) nameInput.focus();
      return;
    }

    const langSelect = document.getElementById('setup-lang');
    const currencySelect = document.getElementById('setup-currency');
    const latInput = document.getElementById('setup-lat');
    const lngInput = document.getElementById('setup-lng');
    const dobInput = document.getElementById('setup-dob');
    const bioInput = document.getElementById('setup-bio');

    if (!latInput || !latInput.value || isNaN(parseFloat(latInput.value)) || !lngInput || !lngInput.value || isNaN(parseFloat(lngInput.value))) {
      Utils.toast('Please detect your location or enter coordinates manually', 'warning');
      const err = document.getElementById('setup-loc-err');
      if (err) { err.textContent = 'Location is required'; err.classList.add('show'); }
      return; // Prevent form submission without location
    }

    this._submitting = true;
    const finishBtn = document.getElementById('setup-finish-btn');
    if (finishBtn) { finishBtn.disabled = true; finishBtn.classList.add('btn-loading'); }

    try {
      const language = langSelect ? langSelect.value : 'en';
      const currency = currencySelect ? currencySelect.value : 'USD';
      const lat = parseFloat(latInput.value);
      const lng = parseFloat(lngInput.value);
      const gender = this.selectedGender || 'male';
      let dob = dobInput ? dobInput.value : '';
      if (dob) {
        const parts = dob.split('-');
        if (parts.length === 3) {
          const y = parseInt(parts[0], 10), m = parseInt(parts[1], 10), d = parseInt(parts[2], 10);
          const maxDay = new Date(y, m, 0).getDate();
          if (d > maxDay) dob = `${y}-${String(m).padStart(2,'0')}-${String(maxDay).padStart(2,'0')}`;
        }
      }
      const bio = bioInput ? bioInput.value.trim() : '';

      const user = {
        id: 'local_' + Date.now(),
        name: name,
        email: 'local@lamim.offline',
        role: 'user',
        gender: gender,
        dob: dob,
        bio: bio,
        avatar: null,
        location: '',
        createdAt: new Date().toISOString()
      };

      const settings = DB.getSettings();
      settings.language = language;
      settings.currency = currency;
      settings.lat = lat;
      settings.lng = lng;

      if (typeof App !== 'undefined' && App.setLang) {
        App.setLang(language);
      } else {
        try { localStorage.setItem('lamim_lang', language); } catch {}
      }

      // Generate a unique virtual card number for this account at creation time
      if (!settings.cardNumber) {
        const grp = () => Array.from({ length: 4 }, () => Math.floor(Math.random() * 10)).join('');
        settings.cardNumber = grp() + grp() + grp() + grp();
      }

      const statusText = document.getElementById('setup-location-status');
      if (statusText && statusText.textContent.startsWith('Detected: ')) {
        settings.locationName = statusText.textContent.replace('Detected: ', '');
      } else {
        settings.locationName = lat.toFixed(2) + ', ' + lng.toFixed(2);
      }

      DB.setUser(user);
      DB.setSettings(settings);

      Utils.toast('Welcome, ' + name + '!', 'success');

      setTimeout(() => {
        App.showDashboard();
        this._submitting = false;
        if (finishBtn) { finishBtn.disabled = false; finishBtn.classList.remove('btn-loading'); }
      }, 400);
    } catch (err) {
      console.error('[Auth] submitSetup error:', err);
      Utils.toast('Something went wrong. Please try again.', 'error');
      this._submitting = false;
      if (finishBtn) { finishBtn.disabled = false; finishBtn.classList.remove('btn-loading'); }
    }
  },

  resetSetup() {
    this.selectedGender = null;
    this._dobReady = false;
    this._submitting = false;
    ['setup-name', 'setup-dob', 'setup-lat', 'setup-lng', 'setup-bio'].forEach((id) => {
      const el = document.getElementById(id);
      if (el) el.value = '';
    });
    const nameInput = document.getElementById('setup-name');
    if (nameInput) nameInput.classList.remove('input-error');
    const nameErr = document.getElementById('setup-name-err');
    if (nameErr) { nameErr.textContent = ''; nameErr.classList.remove('show'); }
    const locErr = document.getElementById('setup-loc-err');
    if (locErr) { locErr.textContent = ''; locErr.classList.remove('show'); }
    ['setup-gender-male', 'setup-gender-female'].forEach((id) => {
      const el = document.getElementById(id);
      if (el) el.classList.remove('active');
    });
    this.setLang('en');
    this.setCurrency('USD');
    const finishBtn = document.getElementById('setup-finish-btn');
    if (finishBtn) { finishBtn.disabled = false; finishBtn.classList.remove('btn-loading'); }
    this.goToStep(1);
  },

  bindSetup() {
    if (this._setupBound) return;
    this._setupBound = true;
    const nameInput = document.getElementById('setup-name');
    if (nameInput) {
      nameInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); this.submitSetup(); }
      });
      nameInput.addEventListener('input', () => {
        if (nameInput.value.trim()) {
          nameInput.classList.remove('input-error');
          const err = document.getElementById('setup-name-err');
          if (err) err.classList.remove('show');
        }
      });
    }
  },

  logout() {
    const isBn = (localStorage.getItem('lamim_lang') || 'en') === 'bn';
    const title = isBn ? 'লগ আউট' : 'Log Out';
    const msg = isBn
      ? 'লগ আউট করবেন এবং ওয়েলকাম স্ক্রিনে ফিরে যাবেন। আপনার লোকাল ডাটা এই ডিভাইসেই থাকবে।'
      : 'Log out and return to the welcome screen. Your local data stays on this device.';
    Utils.dangerConfirm({
      title,
      message: msg,
      icon: '<svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path><polyline points="16 17 21 12 16 7"></polyline><line x1="21" y1="12" x2="9" y2="12"></line></svg>',
      color: '#8b5cf6',
      confirmText: isBn ? 'লগ আউট' : 'Log Out',
      onConfirm: () => {
        DB.remove('lamim_user');
        document.body.classList.remove('home-active');
        Utils.toast(isBn ? 'লগ আউট করা হয়েছে' : 'Logged out', 'info');
        this.resetSetup();
        setTimeout(() => { if (typeof App !== 'undefined') App.showPage('setup'); }, 400);
      }
    });
  }
};


/* --- home.js --- */
/* =============================================
   LAMIM — HOME MODULE
   ============================================= */
const Home = {
  countdownInterval: null,
  _clockInterval: null,

  init() {
    this.render();
    this.startClock();
    this.updateNextPrayer();
    this.updateSpiritScore();
    this.updateSalahTimeline();
    this.renderDailyInsights();
    this.bindAuroraScrollPause();
  },

  onDataUpdated() {
    this.updateNextPrayer();
    this.updateSalahTimeline();
  },

  bindAuroraScrollPause() {
    // No-op: Aurora background disabled for ultra-smooth 60fps scrolling
  },

  destroy() {
    if (this._clockInterval) {
      clearInterval(this._clockInterval);
      this._clockInterval = null;
    }
    if (this.countdownInterval) {
      clearInterval(this.countdownInterval);
      this.countdownInterval = null;
    }
    if (this._nextPrayerTimeout) {
      clearTimeout(this._nextPrayerTimeout);
      this._nextPrayerTimeout = null;
    }
    if (this._auroraHandler) {
      window.removeEventListener('scroll', this._auroraHandler);
      this._auroraHandler = null;
      this._auroraBound = false;
    }
  },

  render() {
    const greeting = this.getGreeting();
    const user = DB.getUser() || {};
    const greetingEl = document.getElementById('home-greeting');
    if (greetingEl) {
      greetingEl.textContent = user.name ? `${greeting}, ${user.name}` : greeting;
    }
  },

  getGreeting() {
    const lang = (typeof App !== 'undefined' && App.lang) || 'en';
    const hour = new Date().getHours();
    const isBn = lang === 'bn';
    if (hour < 4) return isBn ? 'শুভ রাত্রি' : 'Late Night';
    if (hour < 12) return isBn ? 'সুপ্রভাত' : 'Good Morning';
    if (hour < 18) return isBn ? 'শুভ অপরাহ্ন' : 'Good Afternoon';
    return isBn ? 'শুভ সন্ধ্যা' : 'Good Evening';
  },

  startClock() {
    if (this._clockInterval) clearInterval(this._clockInterval);

    const updateClock = () => {
      const now = new Date();
      const dateEl = document.getElementById('home-date');
      const hijriEl = document.getElementById('home-hijri-date');

      if (dateEl) {
        dateEl.textContent = now.toLocaleDateString(
          (typeof App !== 'undefined' && App.lang) === 'bn' ? 'bn-BD' : 'en-US',
          { weekday: 'long', month: 'long', day: 'numeric' }
        );
      }
      if (hijriEl && Utils.toHijri) {
        hijriEl.textContent = Utils.toHijri(now);
      }
      
      // Update quote & insights every minute dynamically
      this.renderDailyInsights();
    };

    updateClock();
    this._clockInterval = setInterval(updateClock, 60000);
  },

  updateNextPrayer() {
    const times = Utils.calcPrayerTimes();
    const next = Utils.getNextPrayer(times);

    const cardEl = document.getElementById('home-next-prayer');
    const nameEl = document.getElementById('home-next-prayer-name');
    const timeEl = document.getElementById('home-next-prayer-time');
    const countdownEl = document.getElementById('home-next-prayer-countdown');

    if (next && cardEl) {
      cardEl.style.display = 'flex';
      if (nameEl) nameEl.textContent = next.name.charAt(0).toUpperCase() + next.name.slice(1);
      if (timeEl) timeEl.textContent = next.label;

      if (this.countdownInterval) clearInterval(this.countdownInterval);
      if (this._nextPrayerTimeout) clearTimeout(this._nextPrayerTimeout);
      
      const updateCountdown = () => {
        if (countdownEl) {
          countdownEl.textContent = Utils.countdownTo(next.time);
          if (next.time - new Date() <= 0) {
            clearInterval(this.countdownInterval);
            this._nextPrayerTimeout = setTimeout(() => this.updateNextPrayer(), 1000);
          }
        }
      };
      updateCountdown();
      this.countdownInterval = setInterval(updateCountdown, 1000);
    }
  },

  updateSpiritScore() {
    const user = DB.getUser();
    const scoreEl = document.getElementById('home-spirit-score');
    if (scoreEl && user) {
      scoreEl.textContent = Math.round(user.spirit_score || 0);
    }
  },

  updateSalahTimeline() {
    const today = Utils.todayStr();
    const salah = DB.getSalah(today);
    const score = Utils.salahScore(salah);
    const container = document.getElementById('home-salah-timeline');
    const countBadge = document.getElementById('home-salah-count-badge');

    if (countBadge) countBadge.textContent = `${score.done}/5`;

    if (container) {
      const prayers = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
      const nodes = container.querySelectorAll('.timeline-node');
      if (nodes.length === prayers.length) {
        prayers.forEach((p, idx) => {
          const key = p.toLowerCase();
          const status = salah[key];
          const node = nodes[idx];
          node.className = `timeline-node${status ? ' status-' + status : ''}`;
        });
        return;
      }
      let html = '';
      prayers.forEach(p => {
        const key = p.toLowerCase();
        const status = salah[key];
        let statusClass = status ? `status-${status}` : '';
        const initial = p.charAt(0);
        html += `
          <div class="timeline-node ${statusClass}" onclick="App.switchSection('salah')" style="cursor:pointer;" role="button" aria-label="Go to Salah section for ${p}">
            <div class="timeline-dot">${initial}</div>
            <span class="timeline-label">${p}</span>
          </div>
        `;
      });
      container.innerHTML = html;
    }
  },

  renderDailyInsights() {
    // 1. Dhikr Count
    const today = Utils.todayStr();
    const dhikrData = DB.getDhikr(today) || {};
    let totalDhikr = 0;
    Object.values(dhikrData).forEach(v => {
      if (typeof v === 'number') totalDhikr += v;
    });
    const dhikrEl = document.getElementById('home-insight-dhikr');
    if (dhikrEl) dhikrEl.textContent = totalDhikr;

    // 2. Streak — use Salah streak (perfect days)
    const salahStreak = DB.getSalahStreak();
    const streakEl = document.getElementById('home-insight-streak');
    if (streakEl) streakEl.textContent = salahStreak.perfect || 0;

    // 3. Dynamic Daily Quote
    const quote = Utils.getQuote();
    const arabicEl = document.getElementById('home-quote-arabic');
    const translationEl = document.getElementById('home-quote-translation');
    const cardEl = document.querySelector('.home-quote-card');
    
    if (arabicEl && translationEl && quote) {
      // First load check
      if (arabicEl.textContent === '...' || arabicEl.textContent.trim() === '') {
        arabicEl.textContent = quote.arabic;
        translationEl.textContent = quote.translation;
      } 
      // If the quote has changed, animate it
      else if (arabicEl.textContent !== quote.arabic) {
        if (cardEl) {
          if (this._quoteFadeTimeout) clearTimeout(this._quoteFadeTimeout);
          cardEl.classList.add('quote-anim-hidden');
          this._quoteFadeTimeout = setTimeout(() => {
            arabicEl.textContent = quote.arabic;
            translationEl.textContent = quote.translation;
            cardEl.classList.remove('quote-anim-hidden');
          }, 500);
        } else {
          arabicEl.textContent = quote.arabic;
          translationEl.textContent = quote.translation;
        }
      }
    }
  }
};

window.Home = Home;



